@push('scripts')
<script>document.querySelectorAll('.registro-llamada').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button'),status=form.querySelector('.resultado-llamada');button.disabled=true;try{const body=Object.fromEntries(new FormData(form));body.result=form.querySelector('select').selectedOptions[0].text;for(const key of ['fecha_reprogramada','motivo_derivacion'])if(!body[key])delete body[key];const res=await fetch(form.action,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':body._token},body:JSON.stringify(body)});const data=await res.json();if(!res.ok||!data.success)throw Error(Object.values(data.errors||{}).flat().join('\n')||data.message||data.error||'No se pudo registrar');status.textContent='Llamada guardada. Actualizando el avance…';location.reload();}catch(error){status.textContent=error.message;button.disabled=false;}}));</script>
